public sealed class TugAppearanceIntegrationTests
{
    const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
    static Type Sports(string name)=>Type.GetType("LWS.TruckSports."+name+", Assembly-CSharp",true);
    static object Get(object owner,string name)=>owner.GetType().GetField(name,Any) is FieldInfo field?field.GetValue(owner):owner.GetType().GetProperty(name,Any).GetValue(owner);
    static void Set(object owner,string name,object value){if(owner.GetType().GetField(name,Any) is FieldInfo field)field.SetValue(owner,value);else owner.GetType().GetProperty(name,Any).SetValue(owner,value);}
    static object Call(object owner,string name,params object[] args)=>owner.GetType().GetMethods(Any).Single(method=>method.Name==name&&method.GetParameters().Length==args.Length).Invoke(owner,args);
    static object Registry(string name,params object[] args)=>Sports("SportsParticipantRegistry").GetMethod(name).Invoke(null,args);
    Component match;Component[] trucks;object[] hosts,rigs;string[] ids;IDisposable lease;GameObject isolation;
    [TearDown]public void Cleanup(){Time.timeScale=1;if(match!=null)Call(match,"SetupScreen");if(isolation!=null)UnityEngine.Object.DestroyImmediate(isolation);Registry("ForgetCache");lease?.Dispose();lease=null;}
    IEnumerator Load()
    {
        lease=(IDisposable)Sports("SportsPrefs").GetMethod("IsolateValidation").Invoke(null,new object[]{"TugAppearance"+Guid.NewGuid().ToString("N")});Registry("ForgetCache");isolation=new GameObject("Explicit Tug appearance-only native fixture");UnityEngine.Object.DontDestroyOnLoad(isolation);isolation.AddComponent(Sports("SportsProbeInputIsolation"));EditorSceneManager.LoadSceneInPlayMode("Assets/TruckTugOfWar/Scenes/TruckTugOfWar.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;match=(Component)UnityEngine.Object.FindAnyObjectByType(Type.GetType("LWS.TruckTugOfWar.TugMatch, Assembly-CSharp",true));Assert.That(match,Is.Not.Null);Set(match,"teamA",4);Set(match,"teamB",4);Call(match,"AllBots");Call(match,"NormalizeSetup");trucks=((Array)Get(match,"trucks")).Cast<Component>().ToArray();rigs=((Array)Get(match,"fragments")).Cast<object>().ToArray();hosts=((Array)Get(match,"tugAppearanceHosts")).Cast<object>().ToArray();Assert.That(hosts.Length,Is.EqualTo(8),"Invoke BindMissingTugAppearanceHosts first.");Assert.That(((Array)Get(match,"appearanceHosts")),Is.Empty,"Tug's original zero-scale reset must happen before local body composition.");ids=new string[8];for(int i=0;i<8;i++){ids[i]=(string)Get(Registry("Create","Same Tug Driver"),"id");Registry("UseInSeat",i,ids[i]);Save(ids[i],i%2==0?"truck.fire":"truck.monster");Assert.That(Get(trucks[i],"appearanceHost"),Is.SameAs(hosts[i]));Assert.That(Get(rigs[i],"truck"),Is.SameAs(trucks[i]));Assert.That(Get(rigs[i],"sourceBody"),Is.Null);var binding=trucks[i].GetComponent(Sports("SportsWheelMeshBinding"));CollectionAssert.AreEqual((Transform[])Get(binding,"meshes"),(Transform[])Get(Get(hosts[i],"fragmentPresentation"),"eventWheelPieceSources"));}Call(match,"RefreshParticipants",false);
    }
    static void Save(string id,string body){var draft=Registry("GetAppearance",id);Set(draft,"bodyId",body);((IList)Get(draft,"selections")).Clear();Registry("TrySetAppearance",id,draft);Registry("ForgetCache");Assert.That(Get(Registry("GetAppearance",id),"bodyId"),Is.EqualTo(body));}
    string PhysicsSignature(){var text=new StringBuilder();foreach(var truck in trucks){foreach(var body in truck.GetComponentsInChildren<Rigidbody>(true))text.Append("B").Append(body.GetInstanceID()).Append(':').Append(body.mass).Append(':').Append(body.centerOfMass.ToString("R")).Append(':').Append(body.linearDamping).Append(':').Append(body.angularDamping).Append(':').Append(body.constraints).Append(':').Append(body==(Rigidbody)Get(truck,"body")?body.inertiaTensor.ToString("R"):"original zero-scale pooled geometry; derived inertia follows native activation");foreach(var shape in truck.GetComponentsInChildren<Collider>(true)){text.Append("C").Append(shape.GetInstanceID()).Append(':').Append(shape.GetType().Name).Append(':').Append(shape.isTrigger);if(shape is BoxCollider box)text.Append(':').Append(box.center.ToString("R")).Append(':').Append(box.size.ToString("R"));if(shape is MeshCollider mesh)text.Append(':').Append(mesh.sharedMesh!=null?mesh.sharedMesh.GetInstanceID():0);}foreach(var wheel in (Array)Get(truck,"wheels")){var data=Get(wheel,"wheel");var spring=Get(wheel,"spring");text.Append("W").Append(((Component)wheel).GetInstanceID()).Append(':').Append(Get(data,"radius")).Append(':').Append(Get(data,"width")).Append(':').Append(Get(spring,"maxLength")).Append(':').Append(Get(spring,"maxForce"));}}return text.ToString();}
    IEnumerator StartOriginal(bool appearances)
    {
        var saved=(Array)Get(match,"tugAppearanceHosts");if(!appearances){Set(match,"tugAppearanceHosts",Array.CreateInstance(Sports("SportsTruckAppearanceHost"),0));foreach(var truck in trucks)Set(truck,"appearanceHost",null);}
        try{Assert.That(Call(match,"StartMatch"),Is.EqualTo(true));double deadline=Time.realtimeSinceStartupAsDouble+8;while(Get(match,"Stage").ToString()=="Countdown"&&Time.realtimeSinceStartupAsDouble<deadline)yield return null;Assert.That(Get(match,"Stage").ToString(),Is.EqualTo("Pull"));yield return null;yield return null;}
        finally{if(!appearances){Set(match,"tugAppearanceHosts",saved);for(int i=0;i<8;i++)Set(trucks[i],"appearanceHost",hosts[i]);}}
    }
    void Hold(){((Behaviour)match).enabled=false;foreach(var truck in trucks){Call(truck,"Power",false);((Rigidbody)Get(truck,"body")).isKinematic=true;}foreach(var header in (Rigidbody[])Get(match,"headers"))header.isKinematic=true;}
    [UnityTest,Timeout(180000)]public IEnumerator SevenBodiesUseExactExistingEventTruckWreckPiecesAndRecoverChangedBodyAfterZeroScaleRematch()
    {
        yield return Load();yield return StartOriginal(false);Hold();string physical=PhysicsSignature();var headers=((Rigidbody[])Get(match,"headers")).ToArray();var ropes=((Array)Get(match,"ropes")).Cast<object>().ToArray();var trails=((Array)Get(Get(match,"ruts"),"trails")).Cast<object>().ToArray();var fire=((Array)Get(match,"fire")).Cast<object>().ToArray();var replay=Get(match,"replay");var sources=((Transform[])Get(replay,"sources")).ToArray();var ghosts=((Transform[])Get(replay,"ghosts")).ToArray();var pieces=((Array)Get(rigs[0],"pieces")).Cast<object>().ToArray();var pieceBodies=pieces.Select(piece=>(Rigidbody)Get(piece,"body")).ToArray();var pieceShapes=pieces.Select(piece=>(Collider)Get(piece,"collider")).ToArray();var presenter=Get(hosts[0],"fragmentPresentation");
        foreach(string body in new[]{"truck.fire","truck.monster","truck.lifted","semi.lowrider","novelty.hotdog","novelty.icecream","semi.standard"})
        {
            Save(ids[0],body);Call(match,"RefreshParticipants",false);Call(match,"BeginHeat");Assert.That(Get(hosts[0],"EffectiveBodyId"),Is.EqualTo(body));Assert.That(PhysicsSignature(),Is.EqualTo(physical));for(int i=0;i<8;i++)Assert.That(Get(hosts[i],"ProfileId"),Is.EqualTo(ids[i]));var owner=(Rigidbody)Get(trucks[0],"body");owner.isKinematic=false;owner.linearVelocity=new Vector3(2,1,3);owner.angularVelocity=new Vector3(.1f,.2f,-.1f);var velocity=new Vector3[12];var angular=new Vector3[12];for(int i=0;i<12;i++){var source=(Transform)Get(pieces[i],"source");var direction=source.TransformPoint(source.GetComponent<MeshFilter>().sharedMesh.bounds.center)-owner.worldCenterOfMass;if(direction.sqrMagnitude<.01f)direction=Vector3.up;direction.Normalize();velocity[i]=Vector3.ClampMagnitude(owner.GetPointVelocity(source.position),30)+direction*4+Vector3.up*4;angular[i]=Vector3.ClampMagnitude(owner.angularVelocity,10)+new Vector3(4,6,3);}Set(match,"Clock",4f);Call(match,"CaptureAppearanceReplay");int builds=(int)Get(presenter,"PoolBuilds");Call(rigs[0],"Burst");Assert.That(Get(presenter,"LastBurstBodyId"),Is.EqualTo(body));Assert.That(((Transform)Get(trucks[0],"visuals")).localScale,Is.EqualTo(Vector3.zero));for(int i=0;i<12;i++){Assert.That(Get(pieces[i],"body"),Is.SameAs(pieceBodies[i]));Assert.That(Get(pieces[i],"collider"),Is.SameAs(pieceShapes[i]));Assert.That(pieceShapes[i].enabled,Is.True);Assert.That(((Renderer)Get(pieces[i],"renderer")).enabled,Is.False);Assert.That(Vector3.Distance(pieceBodies[i].linearVelocity,velocity[i]),Is.LessThan(.0002f));Assert.That(Vector3.Distance(pieceBodies[i].angularVelocity,angular[i]),Is.LessThan(.0002f));}Assert.That(((Renderer[])Get(presenter,"ExteriorRenderers")).Any(renderer=>renderer.enabled&&renderer.gameObject.activeInHierarchy),Is.True);Set(match,"Clock",4.2f);Call(match,"CaptureAppearanceReplay");Call(rigs[0],"ResetBody");Assert.That(Get(presenter,"PoolBuilds"),Is.EqualTo(builds));Assert.That(((Transform)Get(trucks[0],"visuals")).localScale,Is.Not.EqualTo(Vector3.zero));Assert.That(PhysicsSignature(),Is.EqualTo(physical));CollectionAssert.AreEqual(headers,(Rigidbody[])Get(match,"headers"));CollectionAssert.AreEqual(ropes,((Array)Get(match,"ropes")).Cast<object>());CollectionAssert.AreEqual(trails,((Array)Get(Get(match,"ruts"),"trails")).Cast<object>());CollectionAssert.AreEqual(fire,((Array)Get(match,"fire")).Cast<object>());CollectionAssert.AreEqual(sources,(Transform[])Get(replay,"sources"));CollectionAssert.AreEqual(ghosts,(Transform[])Get(replay,"ghosts"));
        }
        Call(rigs[0],"Burst");Assert.That(((Transform)Get(trucks[0],"visuals")).localScale,Is.EqualTo(Vector3.zero));Save(ids[0],"novelty.icecream");Call(match,"RefreshParticipants",false);Call(match,"SetupScreen");Assert.That(Call(match,"StartMatch"),Is.EqualTo(true));Assert.That(Get(hosts[0],"EffectiveBodyId"),Is.EqualTo("novelty.icecream"));Assert.That(((Transform)Get(trucks[0],"visuals")).localScale,Is.Not.EqualTo(Vector3.zero));Assert.That(((Transform)Get(hosts[0],"AppearanceRoot")).GetComponentsInChildren<Transform>(true).All(part=>float.IsFinite(part.localScale.x)&&float.IsFinite(part.localScale.y)&&float.IsFinite(part.localScale.z)),Is.True);Assert.That(PhysicsSignature(),Is.EqualTo(physical));TestContext.WriteLine("TUG_APPEARANCE_ONLY all7 real bodies on original EventTruck12 piece physics/forces, explicit existing wheel sources, source+ghost/root/rope/header/rut/fire identity, pool reuse and changed-body rematch after original zero-scale Burst. Original gameplay/QTE/traction unchanged; controlled composition samples, not gameplay redesign/art acceptance.");
    }
    [UnityTest,Timeout(180000)]public IEnumerator ActualOriginalLedgeLossAndLavaFallBurstSelectedBodyThenUseOriginalRecordedReplayAndPause()
    {
        yield return Load();yield return StartOriginal(true);var owner=(Rigidbody)Get(trucks[0],"body");var position=owner.position;position.x=0;owner.position=position;owner.transform.position=position;UnityEngine.Physics.SyncTransforms();double deadline=Time.realtimeSinceStartupAsDouble+14;while(Get(match,"Stage").ToString()!="Replay"&&Time.realtimeSinceStartupAsDouble<deadline)yield return null;Assert.That(Get(match,"Stage").ToString(),Is.EqualTo("Replay"),"Original accepted ledge loss, real fall below-48 and six-second aftermath must reach original replay.");var presenter=Get(hosts[0],"fragmentPresentation");Assert.That((int)Get(presenter,"ActualBursts"),Is.GreaterThan(0));Assert.That(Get(presenter,"LastBurstBodyId"),Is.EqualTo("truck.fire"));var replay=Get(match,"replay");Assert.That(Get(replay,"Playing"),Is.EqualTo(true));var ghost=((Transform[])Get(replay,"ghosts"))[0];Assert.That(ghost.GetComponentsInChildren<Rigidbody>(true),Is.Empty);Assert.That(ghost.GetComponentsInChildren<Collider>(true),Is.Empty);Assert.That(ghost.GetComponentsInChildren<Renderer>(true).Any(renderer=>renderer.enabled&&renderer.gameObject.activeInHierarchy&&renderer.transform.lossyScale.sqrMagnitude>.001f),Is.True);var record=Get(replay,"roots");Assert.That(Call(replay,"RefreshAppearanceSources",new[]{0,1,2,3,4,5,6,7},true),Is.EqualTo(false));Assert.That(Get(replay,"roots"),Is.SameAs(record));Call(match,"Pause",0,false);yield return null;yield return null;float cursor=(float)Get(replay,"Cursor");yield return null;yield return null;Assert.That(Get(replay,"Cursor"),Is.EqualTo(cursor));Call(match,"Resume");Call(match,"ExtraAction","replayskip");yield return new WaitForFixedUpdate();Assert.That(Get(replay,"Playing"),Is.EqualTo(false));Assert.That(((Transform[])Get(replay,"ghosts")).All(root=>!root.gameObject.activeSelf),Is.True);TestContext.WriteLine("TUG_ACTUAL_APPEARANCE_BOUNDARY controlled initial ledge position; original rules accept loss, actual gravity fall and existing lava threshold Burst, original actual-transform replay/playing guard/pause/skip cleanup. No score, traction, heave timing or physics retuning; human/art acceptance unperformed.");
    }
}
